import {Breadcrumbs} from "./ui";export default function PageHero({eyebrow,title,copy,crumbs=[]}:{eyebrow:string;title:string;copy:string;crumbs?:{label:string;href?:string}[]}){return <section className="hero section"><div className="container">{crumbs.length>0&&<Breadcrumbs items={crumbs}/>}<div className="eyebrow">{eyebrow}</div><h1 className="display" style={{maxWidth:950,margin:".7rem 0 1rem"}}>{title}</h1><p className="lead" style={{maxWidth:780}}>{copy}</p></div></section>}
